var pid = 'hk' + (++this._pid);
var desc = [];
if (it.playCount) { desc.push(this.fmtNum(it.playCount) + '播放'); }
if (it.likeCount) { desc.push(this.fmtNum(it.likeCount) + '赞'); }
if ((it.coins || 0) > 0) { desc.push('付费' + it.coins + '币'); }
return {title: this.clean(it.title || ''), desc: desc.join(' · ').substring(0, 60), pic: it.cover ? this.hkPic(this.cover(it.cover)) : '', url: this.detailUrl('app', it.id), col_type: 'movie_3', extra: {id: pid}, tags: this.tagNames(it.tags)};
},
fmtNum: function(n) {
n = parseInt(n, 10) || 0;
if (n >= 100000000) { return (Math.floor(n / 1000000) / 100) + '亿'; }
if (n >= 10000) { return (Math.floor(n / 100) / 100) + '万'; }
return String(n);
},
videoItems: function(d) {
var out = [];
var items = (d && d.videos) || [];
var seen = {};
for (var i = 0; i < items.length; i++) {
var it = items[i] || {};
if (!it.id || seen[it.id]) { continue; }
seen[it.id] = 1;
if (!this.clean(it.title || '')) { continue; }
out.push(this.videoCard(it));
}
return {items: out, hasNext: !!(d && d.hasNext)};
},
appList: function(sort, pg, size) {
var r = this.apiJson('/api/app/vid/home/new/list', {pageNumber: pg, pageSize: size, sortType: sort}, 'GET', null, 30, true);
if (!r || r.code !== 200 || !r.data) { return {items: [], hasNext: false}; }
return this.videoItems(r.data);
},
tagList: function() {
var seen = {};
var out = [];
for (var pg = 1; pg <= 2; pg++) {
var r = this.appList('1', pg, 24);
for (var i = 0; i < r.items.length; i++) {
var tg = this.tagNames(r.items[i].tags);
for (var j = 0; j < tg.length; j++) {
var t = tg[j];
if (!t || seen[t]) { continue; }
seen[t] = 1;
out.push(t);
}
}
if (!r.hasNext) { break; }
}
return out;
},
detailUrl: function(tp, id) {
return 'hiker://empty?type=' + tp + '&id=' + id + '@rule=js:$.require("hiker://page/erji")';
},
tagUrl: function(tag) {
return 'hiker://empty?tag=' + encodeURIComponent(tag) + '@rule=js:$.require("hiker://page/tag")';
},
tagsView: function(d) {
var tags = this.tagList();
d.push({title: '热门标签', col_type: 'text_1', extra: {lineVisible: false}});
if (!tags.length) {
d.push({title: '暂无标签', col_type: 'text_center_1'});
return;
}
for (var i = 0; i < tags.length; i++) {
d.push({title: '#' + tags[i], url: this.tagUrl(tags[i]), col_type: 'text_3', extra: {lineVisible: false}});
}
}
};
var d = [];
HK.tagsView(d);
setResult(d);
"}]
